def prime_fib(n: int):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    fib_numbers = []
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
        fib_numbers.append(a)

    prime_fib_numbers = []
    for num in fib_numbers:
        if is_prime(num):
            prime_fib_numbers.append(num)

    return prime_fib_numbers[n-1]
```

